function validate(input) {
  const [{ RequestAccepted = [] }] = input;
  const pairs = new Set(), counts = new Map();
  for (const [a, b] of RequestAccepted) {
    if (a === null || b === null) return 'Every request needs both user ids.';
    if (a === b) return `User ${a} cannot befriend themselves.`;
    const key = a < b ? `${a},${b}` : `${b},${a}`;
    if (pairs.has(key)) return `Users ${a} and ${b} are paired twice.`;
    pairs.add(key);
    counts.set(a, (counts.get(a) ?? 0) + 1);
    counts.set(b, (counts.get(b) ?? 0) + 1);
  }
  if (counts.size === 0) return 'The table needs at least one request.';
  const best = Math.max(...counts.values());
  if ([...counts.values()].filter(c => c === best).length > 1) return 'Exactly one user must have the most friends.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pool = small ? 6 : 300, wanted = small ? Math.floor(rand() * 7) : 1900;
  const date = () => `2016-0${1 + Math.floor(rand() * 9)}-${String(1 + Math.floor(rand() * 28)).padStart(2, '0')}`;
  const pairs = new Set(), counts = new Map(), RequestAccepted = [];
  const add = (a, b) => {
    pairs.add(a < b ? `${a},${b}` : `${b},${a}`);
    counts.set(a, (counts.get(a) ?? 0) + 1);
    counts.set(b, (counts.get(b) ?? 0) + 1);
    RequestAccepted.push([a, b, date()]);
  };
  for (let tries = 0; RequestAccepted.length < wanted && tries < wanted * 4; tries++) {
    const a = 1 + Math.floor(rand() * pool), b = 1 + Math.floor(rand() * pool);
    if (a !== b && !pairs.has(a < b ? `${a},${b}` : `${b},${a}`)) add(a, b);
  }
  // Break a tie for the top (or fill an empty table) by giving one leader a friend with a fresh id.
  let fresh = pool + 1;
  for (;;) {
    const values = [...counts.values()], best = values.length ? Math.max(...values) : 0;
    if (best > 0 && values.filter(c => c === best).length === 1) break;
    const leader = best > 0 ? [...counts].find(([, c]) => c === best)[0] : fresh++;
    if (rand() < 0.5) add(leader, fresh++); else add(fresh++, leader);
  }
  return [{ RequestAccepted }];
}
